    public OATree createSearchTree() {
        OATree tree = new OATree();
        tree.setPreferredSize(10, 18);
        OATreeTitleNode tnode;
        OATreeNode node, node2;
    
        tnode = new OATreeTitleNode(getModel().getPluralDisplayName());
        tnode.setIcon(ApplicationTypeJfc.getTitleIcon());
        tree.add(tnode);
        node = new OATreeNode(ApplicationTypeJfc.PP_Display, ModelDelegate.getApplicationTypes().createSharedHub(), getHub()) {
            @Override
            public void onDoubleClick(Object obj, MouseEvent e) {
                ApplicationTypeJfcBase.this.onDoubleClickTreeNode();
            }
        };
        if (getModel().getAllowMultiSelect()) {
            node.setSelectedHub(getModel().getMultiSelectHub());
        }
        node.setIcon(ApplicationTypeJfc.getIcon());
        node.setForegroundColorProperty(ApplicationTypeJfc.PP_ForeColor);
        node.setBackgroundColorProperty(ApplicationTypeJfc.PP_BackColor);
        node.setIconColorProperty(ApplicationTypeJfc.PP_IconColor);
        node.setImageProperty(ApplicationTypeJfc.PP_Icon);
        node.setFontProperty(ApplicationTypeJfc.PP_Font);
        node.setMaxImageHeight(20);
        node.setMaxImageWidth(32);
        tnode.add(node);
        return tree;
    }
    
    
