    // OnShowCommands
    public void showCardPanel(String name) {
        if (name == null) return;
        if (cardPanel == null) return;
        if (name.equalsIgnoreCase(CARD_ApplicationVersions)) {
            if ( !OAArray.contains(cardPanel.getComponents(), getApplicationVersionsJfc().getCardPanel()) ) {
                cardPanel.add(getApplicationVersionsJfc().getCardPanel(), CARD_ApplicationVersions);
            }
        }
        else if (name.equalsIgnoreCase(CARD_AppUsers)) {
            if ( !OAArray.contains(cardPanel.getComponents(), getAppUsersJfc().getCardPanel()) ) {
                cardPanel.add(getAppUsersJfc().getCardPanel(), CARD_AppUsers);
            }
        }
        else if (name.equalsIgnoreCase(CARD_PropertyValues)) {
            if ( !OAArray.contains(cardPanel.getComponents(), getPropertyValuesJfc().getCardPanel()) ) {
                cardPanel.add(getPropertyValuesJfc().getCardPanel(), CARD_PropertyValues);
            }
        }
        else if (name.equalsIgnoreCase(CARD_ServerApplications)) {
            if ( !OAArray.contains(cardPanel.getComponents(), getServerApplicationsJfc().getCardPanel()) ) {
                cardPanel.add(getServerApplicationsJfc().getCardPanel(), CARD_ServerApplications);
            }
        }
        else if (name.equalsIgnoreCase(CARD_SingleApps)) {
            if ( !OAArray.contains(cardPanel.getComponents(), getSingleAppsJfc().getCardPanel()) ) {
                cardPanel.add(getSingleAppsJfc().getCardPanel(), CARD_SingleApps);
            }
        }
        getCardLayout().show(getCardPanel(), name);
    }
