    protected void onHubSearch() {
        getSearchHubJfc().getDialog().setVisible(true);
        if (!getSearchHubJfc().wasSelected()) return;
        if (getModel().getAllowMultiSelect()) {
            getModel().getMultiSelectHub().clear();
            for (ApplicationType applicationType : getSearchHubJfc().getModel().getMultiSelectHub()) {
                if (getHub().contains(applicationType)) {
                    getModel().getMultiSelectHub().add(applicationType);
                }
            }
            getHub().setAO(getModel().getMultiSelectHub().getAt(0));
        }
        else {
            ApplicationType applicationType = getSearchHubJfc().getSelected();
            if (applicationType != null) {
                if (getHub().contains(applicationType)) {
                    getHub().setAO(applicationType);
                }
            }
        }
    }
