    protected ApplicationTypeSearchJfc getSearchJfc() {
        if (jfcSearch == null) {
            jfcSearch = new ApplicationTypeSearchJfc();
        }
        return jfcSearch;
    }
    protected ApplicationType onSearch() {
        getSearchJfc().getModel().beforeInput();
        getSearchJfc().getDialog().setVisible(true);
        ApplicationType applicationType = null;
        if (getSearchJfc().wasSelected()) applicationType = getSearchJfc().getSelected();
        return applicationType;
    }
    // Add
    protected ApplicationTypeSearchJfc getAddJfc() {
        if (jfcAdd == null) {
            jfcAdd = new ApplicationTypeSearchJfc();
        }
        return jfcAdd;
    }
    protected void onAdd() {
        getAddJfc().getDialog().setVisible(true);
        if (!getAddJfc().wasSelected()) return;
        ApplicationType applicationType = getAddJfc().getSelected();
        if (applicationType == null) return;
        getHub().add(applicationType);
        getHub().setAO(applicationType);
    }
    
    
